def transform(grid):
    """Add a one-cell 8-neighbor halo around closed 1-line enclosures.

    Halo cells outside an enclosure become 2; halo cells on its enclosed
    side become 3. Deeper zeros and open line-work remain unchanged.
    """
    h, w = len(grid), len(grid[0])
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    # Enclosed zero regions identify the closed contour components to halo.
    qualifying = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or outside[r][c]:
                continue
            # Any 1 boundary adjacent (8-neighborhood) to an enclosed cavity
            # belongs to a contour that should receive the halo.
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (dr or dc) and 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        qualifying.add((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            adjacent = False
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r + dr, c + dc
                    if (dr or dc) and (nr, nc) in qualifying:
                        adjacent = True
            if adjacent:
                out[r][c] = 2 if outside[r][c] else 3
    return out
