    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and not outside[nr][nc]:
                outside[nr][nc]=True; q.append((nr,nc))

    # Identify all 8-connected strokes; closed strokes are those bordering
    # at least one zero region that cannot reach the grid edge by 4-connectivity.
    components=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen: continue
            comp=[]; seen.add((r,c)); q=deque([(r,c)])
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if (0<=ny<h and 0<=nx<w and grid[ny][nx]==1
                            and (ny,nx) not in seen):
                            seen.add((ny,nx)); q.append((ny,nx))
            components.append(comp)

    out=[row[:] for row in grid]
    for comp in components:
        closed=any(
            0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==0 and not outside[r+dr][c+dc]
            for r,c in comp for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc
        )
        if not closed: continue
        for r,c in comp:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
